python -c 'import re, pathlib, collections; p=pathlib.Path("docs/planning/tasks.md"); s=p.read_text(); heads=list(re.finditer(r"^### (T\\d{3})",s,re.M)); ids=[m.group(1) for m in heads]; edges={i:[] for i in ids}; missing=[]
for n,m in enumerate(heads):
 b=s[m.end():heads[n+1].start() if n+1<len(heads) else len(s)]; dm=re.search(r"Dependencies:\\s*([^\\n]*)",b)
 if dm:
  deps=re.findall(r"T\\d{3}",dm.group(1)); edges[m.group(1)]=deps
  missing += [(m.group(1),d) for d in deps if d not in edges]
state={}; stack=[]; cycles=[]
def visit(v):
 state[v]=1; stack.append(v)
 for d in edges[v]:
  if state.get(d,0)==0: visit(d)
  elif state.get(d)==1: cycles.append(stack[stack.index(d):]+[d])
 stack.pop(); state[v]=2
for v in ids:
 if not state.get(v): visit(v)
print(f"tasks={len(ids)} unique={len(set(ids))} edges={sum(map(len,edges.values()))}"); print("missing="+repr(missing)); print("cycles="+repr(cycles)); print("T038_dependencies="+repr(edges.get("T038")))'
